#!/usr/bin/env python3
"""Lossless stdlib compressor. Usage: compress.py [--decompress] input output."""
import bz2
import sys
from pathlib import Path


def compress(data):
    return bz2.compress(data, compresslevel=9)


def decompress(data):
    return bz2.decompress(data)


if __name__ == '__main__':
    args = sys.argv[1:]
    decode = args and args[0] == '--decompress'
    if decode:
        args = args[1:]
    if len(args) != 2:
        sys.exit('usage: compress.py [--decompress] input output')
    data = Path(args[0]).read_bytes()
    Path(args[1]).write_bytes(decompress(data) if decode else compress(data))
